@inline(never)
public func portMaskedLowercaseI8(_ v: SIMDInt8.Vector) -> SIMDInt8.Vector {
    SIMDInt8.bitwiseOr(
        v,
        SIMDInt8.selectingOrZero(
            SIMDInt8.lessThan(
                SIMDInt8.subtracting(v, SIMDInt8.repeating(0x41)),
                SIMDInt8.repeating(26)
            ),
            SIMDInt8.repeating(0x20)
        )
    )
}

